import { moduleState, moduleSequences, props, sequences, state } from 'cerebral'
import App from '../'
import assert from 'assert'

describe('GET', () => {
  it('should be able to GET state', () => {
    const rootModule = {
      state: {
        foo: 'bar',
      },
      sequences: {
        foo: [({ get }) => assert.deepStrictEqual(get(state`foo`), 'bar')],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET state with proxy', () => {
    const rootModule = {
      state: {
        foo: 'bar',
      },
      sequences: {
        foo: [({ get }) => assert.deepStrictEqual(get(state.foo), 'bar')],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET module state', () => {
    const rootModule = {
      state: {
        foo: 'bar',
      },
      sequences: {
        foo: [
          ({ get }) => assert.deepStrictEqual(get(moduleState`foo`), 'bar'),
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET module state with proxy', () => {
    const rootModule = {
      state: {
        foo: 'bar',
      },
      sequences: {
        foo: [({ get }) => assert.deepStrictEqual(get(moduleState.foo), 'bar')],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET module state with submodule', () => {
    const rootModule = {
      state: {},
      modules: {
        foo: {
          state: {
            bar: 'bar',
          },
          sequences: {
            baz: [
              ({ get }) => assert.deepStrictEqual(get(moduleState`bar`), 'bar'),
            ],
          },
        },
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo.baz')()
  })
  it('should be able to GET module state with submodule and proxy', () => {
    const rootModule = {
      state: {},
      modules: {
        foo: {
          state: {
            bar: 'bar',
          },
          sequences: {
            baz: [
              ({ get }) => assert.deepStrictEqual(get(moduleState.bar), 'bar'),
            ],
          },
        },
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo.baz')()
  })
  it('should be able to GET props', () => {
    const rootModule = {
      sequences: {
        foo: [({ get }) => assert.deepStrictEqual(get(props`foo`), 'bar')],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')({
      foo: 'bar',
    })
  })
  it('should be able to GET props with proxy', () => {
    const rootModule = {
      sequences: {
        foo: [({ get }) => assert.deepStrictEqual(get(props.foo), 'bar')],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')({
      foo: 'bar',
    })
  })
  it('should be able to GET computed', () => {
    const rootModule = {
      state: {
        fooComputed: () => 'bar',
      },
      sequences: {
        foo: [
          ({ get }) => assert.deepStrictEqual(get(state`fooComputed`), 'bar'),
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET computed with proxy', () => {
    const rootModule = {
      state: {
        fooComputed: () => 'bar',
      },
      sequences: {
        foo: [
          ({ get }) => assert.deepStrictEqual(get(state.fooComputed), 'bar'),
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET sequence', () => {
    const rootModule = {
      sequences: {
        foo: [({ get }) => assert.ok(get(sequences`foo`))],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET sequence with proxy', () => {
    const rootModule = {
      sequences: {
        foo: [({ get }) => assert.ok(get(sequences.foo))],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET module sequences', () => {
    const rootModule = {
      sequences: {
        foo: [({ get }) => assert.ok(get(moduleSequences`foo`))],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET module sequences with proxy', () => {
    const rootModule = {
      sequences: {
        foo: [({ get }) => assert.ok(get(moduleSequences.foo))],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to GET module sequences with submodule', () => {
    const rootModule = {
      state: {},
      modules: {
        baz: {
          sequences: {
            foo: [({ get }) => assert.ok(get(moduleSequences`foo`))],
          },
        },
      },
    }
    const controller = App(rootModule)
    controller.getSequence('baz.foo')()
  })
  it('should be able to GET module sequences with submodule and proxy', () => {
    const rootModule = {
      state: {},
      modules: {
        baz: {
          sequences: {
            foo: [({ get }) => assert.ok(get(moduleSequences.foo))],
          },
        },
      },
    }
    const controller = App(rootModule)
    controller.getSequence('baz.foo')()
  })
  it('should be able to get.path', () => {
    const rootModule = {
      sequences: {
        foo: [
          ({ get }) =>
            assert.strictEqual(get.path(state`foo.bar.baz`), 'foo.bar.baz'),
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to get.path with proxy', () => {
    const rootModule = {
      sequences: {
        foo: [
          ({ get }) =>
            assert.strictEqual(get.path(state.foo.bar.baz), 'foo.bar.baz'),
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to get.path from sequence', () => {
    const rootModule = {
      sequences: {
        foo: [
          ({ get }) =>
            assert.strictEqual(get.path(sequences`foo.bar.baz`), 'foo.bar.baz'),
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
  it('should be able to get.path from sequence with proxy', () => {
    const rootModule = {
      sequences: {
        foo: [
          ({ get }) =>
            assert.strictEqual(get.path(sequences.foo.bar.baz), 'foo.bar.baz'),
        ],
      },
    }
    const controller = App(rootModule)
    controller.getSequence('foo')()
  })
})
